source='''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]

    marker = None
    for r, row in enumerate(grid):
        if row[0] != background and len(set(row)) == 1:
            marker = ("row", r, row[0])
            break
    if marker is None:
        for c in range(w):
            column = {grid[r][c] for r in range(h)}
            if grid[0][c] != background and len(column) == 1:
                marker = ("col", c, grid[0][c])
                break

    orientation, marker_index, marker_color = marker
    object_color = max(
        (color for color in counts if color not in (background, marker_color)),
        key=lambda color: counts[color],
    )
    cells = [
        (r, c)
        for r in range(h)
        for c in range(w)
        if grid[r][c] == object_color
    ]
    min_r = min(r for r, _ in cells)
    max_r = max(r for r, _ in cells)
    min_c = min(c for _, c in cells)
    max_c = max(c for _, c in cells)
    out = [row[:] for row in grid]

    if orientation == "col":
        if marker_index > max_c:
            shift = marker_index - 1 - max_c
        else:
            shift = marker_index + 1 - min_c
        moved = [(r, c + shift) for r, c in cells]
        for r, c in cells:
            out[r][c] = background
        for r, c in moved:
            out[r][c] = object_color
        if shift > 0:
            line = min_c + shift - 1
        elif shift < 0:
            line = max_c + shift + 1
        else:
            line = min_c if marker_index > w / 2 else max_c
        for r in range(h):
            out[r][line] = 8
    else:
        if marker_index > max_r:
            shift = marker_index - 1 - max_r
        else:
            shift = marker_index + 1 - min_r
        moved = [(r + shift, c) for r, c in cells]
        for r, c in cells:
            out[r][c] = background
        for r, c in moved:
            out[r][c] = object_color
        if shift > 0:
            line = min_r + shift - 1
        elif shift < 0:
            line = max_r + shift + 1
        else:
            line = min_r if marker_index > h / 2 else max_r
        out[line] = [8] * w

    return out
'''
